const rows = items.map(i => i.json);

const accounts = rows
  .filter(a => a.active === true && a.deletedAt == null)
  .map(a => {
    const limit = Number(a.dailyConnectionLimit ?? 0);
    const sent = Number(a.connectionSentToday ?? 0);
    const remaining = Math.max(0, limit - sent);
    return {
      accountDbId: a.id,     // for updating connectionSentToday
      accountId: a.accountId, // Unipile account_id
      remaining,
    };
  })
  .filter(a => a.remaining > 0);

const totalRemaining = accounts.reduce((s, a) => s + a.remaining, 0);

return [{
  json: { accounts, totalRemaining }
}];

// ---- helpers ----
function getPublicId(url) {
  if (!url) return null;
  const clean = String(url).trim().split("?")[0].split("#")[0].replace(/\/+$/, "");
  const m = clean.match(/linkedin\.com\/in\/([^\/]+)/i);
  return m?.[1] || null;
}

// ---- read quota payload ----
const quota = $('Compute Remaining Per Account').first().json;

const accounts = quota.accounts; // [{accountDbId, accountId, remaining}]

// learners come from incoming items (your "Get Candidates to Send Conne..." node)
const learners = items.map(i => i.json);

if (!accounts.length || !learners.length) return [];

// ---- allocation ----
const allocations = new Map(accounts.map(a => [a.accountId, []]));
let idx = 0;
const target = Math.ceil(learners.length / accounts.length);

// pass 1: each account up to target but not beyond remaining
for (const a of accounts) {
  const take = Math.min(target, a.remaining);
  for (let k = 0; k < take && idx < learners.length; k++) {
    allocations.get(a.accountId)?.push(learners[idx++]);
  }
}

// pass 2: distribute leftovers round-robin to those with capacity
let rr = 0;
while (idx < learners.length) {
  const a = accounts[rr % accounts.length];
  const list = allocations.get(a.accountId);
  if (list.length < a.remaining) list.push(learners[idx++]);
  rr++;
  if (rr > 100000) break;
}

// ---- flatten output jobs + also compute publicId here ----
const out = [];

for (const a of accounts) {
  const list = allocations.get(a.accountId);

  for (const l of list) {
    const linkedinUrl = l.profileUrlPrimaryLinkUrl || l.linkedinUrl || null;
    const publicId = getPublicId(linkedinUrl);

    // skip if we cannot extract a publicId (safety)
    if (!publicId) continue;

    out.push({
      json: {
        accountId: a.accountId,        // Unipile account_id
        accountDbId: a.accountDbId,    // _linkedinAccount row id
        learnerId: l.id,
        learnerName: l.name,
        linkedinUrl,
        publicId
      }
    });
  }
}

return out;
